package com.progressly.activity.api; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/habits") public class HabitController{final HabitService service;public HabitController(HabitService s){service=s;} UUID u(Authentication a){return UUID.fromString(a.getName());}@PostMapping @ResponseStatus(HttpStatus.CREATED) public HabitDtos.Response create(Authentication a,@Valid @RequestBody HabitDtos.Request r){return service.create(u(a),r);}@GetMapping public List<HabitDtos.Response> list(Authentication a){return service.list(u(a));}@PutMapping("/{id}") public HabitDtos.Response update(Authentication a,@PathVariable UUID id,@Valid @RequestBody HabitDtos.Request r){return service.update(u(a),id,r);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(Authentication a,@PathVariable UUID id){service.delete(u(a),id);}@PostMapping("/{id}/logs") public HabitDtos.LogResponse log(Authentication a,@PathVariable UUID id,@Valid @RequestBody HabitDtos.LogRequest r){return service.log(u(a),id,r);}@GetMapping("/{id}/logs") public List<HabitDtos.LogResponse> history(Authentication a,@PathVariable UUID id){return service.history(u(a),id);}}
